// Find pump operating point (pressure, flow) that minimizes energy consumption
// inputs: [70.0, 20.0]  returns: true
East.function([FloatType, FloatType], BooleanType, ($, initial_pressure, initial_flow) => {
        // Energy model: power = (pressure - 50)^2 + 2*(flow - 30)^2
