                    () => <Icon prefix="fas" name="star" size="2xl" colorPalette="warning" />,
                    () => <Icon prefix="fas" name="heart" size="2xl" colorPalette="danger" />,
                ));

                const onGlyph   = $.const(East.function([StringType], NullType, ($, next) => { $(glyphBind.write(next)); }));
