                                    <Tag variant={dynamicVariant} density={density}>{East.str`ACTIVE → ${dynamicVariant.getTag().upperCase()}`}</Tag>
                                    <Tag variant={Style.StyleVariant("solid")} density={density}>Style.StyleVariant solid</Tag>
